"""Generate lib/svf_sm.s: lib/svf.c's svf_band_pass and svf_band_pass_add loops as SISD kernels (a DO loop each),
bit-identical to selcc's code of the C loops (-DPL_SVF_C).

    python3 modules/machines/plaits/src/dsp/lib/gen_svf_kernel.py

tests/plaits/test_svf_kernel.py checks them against the C on the concrete core.
"""

from __future__ import annotations

from pathlib import Path

HERE = Path(__file__).resolve().parent
OUT = HERE / "svf_sm.s"

HEADER = """\
// machines/plaits: lib/svf.c's band-pass loops, hand-written SISD kernels.
// Generated by lib/gen_svf_kernel.py; do not edit by hand.
//
// svf_bp_kernel(Svf *s, const float *in, float *out, int size, float *gain): out[i] = bp (gain null) or
//   out[i] += *gain * bp (svf_band_pass_add); in may be out. The state (state_1_, state_2_) goes back to s.
//   Bit-identical to selcc's code of the C loops (-DPL_SVF_C) (tests/plaits/test_svf_kernel.py).
//
// State on return: R0-R8, R12, I4 and the flags change; every other register is as on entry (R9-R11, R13-R15 saved
// above I7; I0, I1, M6, L0, L1, L4 pushed through R0, M6 = 1 and L0 = L1 = L4 = 0 set here). No SIMD.
// ABI: as the other kernels (lib/wavetable_sm.s).

.SECTION/PM seg_pmco;
.GLOBAL svf_bp_kernel.;
.COMPRESS;
"""


def kernel() -> str:
    L: list[str] = []

    def a(t: str, c: str = "") -> None:
        line = f"    {t};"
        L.append(f"{line:<56}// {c}" if c else line)

    def lab(n: str) -> None:
        L.append(f"{n}:")

    lab("svf_bp_kernel.")
    dags = ["I0", "I1", "M6", "L0", "L1", "L4"]
    for r in dags:
        a(f"R0 = {r}")
        a("DM(I7, M7) = R0")
    a("M6 = 1")
    for r in ("L0", "L1", "L4"):
        a(f"{r} = 0")
    saves = ["R9", "R10", "R11", "R13", "R14", "R15"]
    a(f"I7=MODIFY (I7,-{len(saves)})(NW)")
    for i, r in enumerate(saves):
        a(f"DM({i + 1}, I7) = {r}")
    a("I4 = R4", "s")
    a("I1 = R8", "in")
    a("I0 = R12", "out")
    a("R13 = DM(0, I4)", "g")
    a("R14 = DM(1, I4)", "r")
    a("R15 = DM(2, I4)", "h")
    a("R10 = DM(3, I4)", "state_1")
    a("R11 = DM(4, I4)", "state_2")
    a("R8 = DM(1, I6)", "size")
    a("R0 = DM(2, I6)", "gain (pointer)")
    a("R1 = 0")
    a("COMP(R8, R1)")
    a("IF LE JUMP _svk_done")
    a("COMP(R0, R1)")
    a("IF EQ JUMP _svk_plain")
    a("R12 = PASS R0")
    a("I4 = R12")
    a("R0 = 0", "(DAG gap)")
    a("R1 = 0")
    a("R2 = 0")
    a("R9 = DM(I4, M5)", "gain")
    a("LCNTR = R8, DO _svk_e0 UNTIL LCE")
    for t, c in body(True):
        a(t, c)
    lab("_svk_e0")
    a("DM(I0, M6) = R1", "out[i] += gain * bp")
    a("JUMP _svk_done")
    lab("_svk_plain")
    a("LCNTR = R8, DO _svk_e1 UNTIL LCE")
    for t, c in body(False):
        a(t, c)
    lab("_svk_e1")
    a("DM(I0, M6) = R3", "out[i] = bp")
    lab("_svk_done")
    a("I4 = R4", "s")
    a("R0 = 0", "(DAG gap)")
    a("R1 = 0")
    a("R2 = 0")
    a("DM(3, I4) = R10")
    a("DM(4, I4) = R11")
    for i, r in enumerate(saves):
        a(f"{r} = DM({i + 1}, I7)")
    a(f"I7=MODIFY (I7,{len(saves)})(NW)")
    for i, r in enumerate(reversed(dags)):
        a(f"{r} = DM({i + 1}, I7)")
    a("I12 = DM(M7, I6)")
    a("JUMP (M14, I12) (DB)")
    a("RFRAME")
    a("NOP")
    return "\n".join(L) + "\n"


def body(add: bool) -> list[tuple[str, str]]:
    b = [
        ("R0 = DM(I1, M6)", "in[i]"),
        ("F1 = F14 * F10", "hp = (in - r s1 - g s1 - s2) * h"),
        ("F1 = F0 - F1", ""),
        ("F2 = F13 * F10", ""),
        ("F1 = F1 - F2", ""),
        ("F1 = F1 - F11", ""),
        ("F1 = F1 * F15", ""),
        ("F3 = F13 * F1", "bp = g hp + s1"),
        ("F3 = F3 + F10", ""),
        ("F10 = F13 * F1", "s1 = g hp + bp"),
        ("F10 = F10 + F3", ""),
        ("F2 = F13 * F3", "lp = g bp + s2"),
        ("F2 = F2 + F11", ""),
        ("F11 = F13 * F3", "s2 = g bp + lp"),
        ("F11 = F11 + F2", ""),
    ]
    if add:
        b += [
            ("F3 = F9 * F3", "gain * bp"),
            ("R1 = DM(I0, M5)", ""),
            ("F1 = F1 + F3", ""),
        ]
    return b


def main() -> None:
    OUT.write_text(HEADER + "\n" + kernel())
    print(OUT)


if __name__ == "__main__":
    main()
